import{_ as a,o as t,c as n,a3 as e}from"./chunks/framework.B9qR_F1m.js";const d=JSON.parse('{"title":"会计要素与会计等式","description":"系统梳理资产、负债、所有者权益、收入、费用、利润六大会计要素，推导静态与动态会计等式，并用完整例题说明交易对等式的影响。","frontmatter":{"title":"会计要素与会计等式","date":"2026-10-20T00:00:00.000Z","updated":"2026-10-22T00:00:00.000Z","subject":"accounting","subjectLabel":"会计学","category":"基础会计","tags":["会计要素","会计等式","借贷记账法"],"description":"系统梳理资产、负债、所有者权益、收入、费用、利润六大会计要素，推导静态与动态会计等式，并用完整例题说明交易对等式的影响。"},"headers":[],"relativePath":"subjects/accounting/fundamentals/accounting-elements.md","filePath":"subjects/accounting/fundamentals/accounting-elements.md","lastUpdated":null}'),p={name:"subjects/accounting/fundamentals/accounting-elements.md"};function m(l,s,c,r,i,o){return t(),n("div",null,[...s[0]||(s[0]=[e('<h1 id="会计要素与会计等式" tabindex="-1">会计要素与会计等式 <a class="header-anchor" href="#会计要素与会计等式" aria-label="Permalink to &quot;会计要素与会计等式&quot;">​</a></h1><blockquote><p><strong>一句话概括</strong>：会计等式是整套账务系统的骨架，任何一笔业务都必须让这个等式保持平衡。</p></blockquote><h2 id="一、六大会计要素" tabindex="-1">一、六大会计要素 <a class="header-anchor" href="#一、六大会计要素" aria-label="Permalink to &quot;一、六大会计要素&quot;">​</a></h2><p>会计要素是对会计对象的基本分类，分为反映<strong>财务状况</strong>与反映<strong>经营成果</strong>两组。</p><h3 id="反映财务状况-资产负债表要素-时点量" tabindex="-1">反映财务状况（资产负债表要素，时点量） <a class="header-anchor" href="#反映财务状况-资产负债表要素-时点量" aria-label="Permalink to &quot;反映财务状况（资产负债表要素，时点量）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>要素</th><th>定义</th><th>确认要点</th><th>常见科目</th></tr></thead><tbody><tr><td>资产</td><td>企业过去的交易或事项形成的、由企业拥有或控制的、预期会给企业带来经济利益的资源</td><td>强调&quot;拥有或控制&quot;与&quot;未来经济利益&quot;，融资租入的固定资产也算资产</td><td>库存现金、应收账款、存货、固定资产、无形资产</td></tr><tr><td>负债</td><td>企业过去的交易或事项形成的、预期会导致经济利益流出企业的现时义务</td><td>必须由<strong>过去</strong>的事项引起，未来签订的合同不构成负债</td><td>短期借款、应付账款、应付职工薪酬、长期借款</td></tr><tr><td>所有者权益</td><td>企业资产扣除负债后由所有者享有的剩余权益</td><td>金额取决于资产与负债的计量，具有<strong>剩余性</strong></td><td>实收资本、资本公积、盈余公积、未分配利润</td></tr></tbody></table><h3 id="反映经营成果-利润表要素-期间量" tabindex="-1">反映经营成果（利润表要素，期间量） <a class="header-anchor" href="#反映经营成果-利润表要素-期间量" aria-label="Permalink to &quot;反映经营成果（利润表要素，期间量）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>要素</th><th>定义</th><th>确认要点</th></tr></thead><tbody><tr><td>收入</td><td>日常活动中形成的、会导致所有者权益增加的、与所有者投入资本无关的经济利益总流入</td><td>强调&quot;日常活动&quot;，出售固定资产的净收益不算收入</td></tr><tr><td>费用</td><td>日常活动中发生的、会导致所有者权益减少的、与向所有者分配利润无关的经济利益总流出</td><td>强调与收入的配比关系</td></tr><tr><td>利润</td><td>一定会计期间的经营成果，包括收入减去费用后的净额、直接计入当期利润的利得和损失</td><td>由收入与费用、利得与损失共同构成</td></tr></tbody></table><blockquote><p><strong>易混点</strong>：收入 ≠ 现金流入。赊销形成收入的同时增加的是应收账款，现金并未流入； 反之，收到客户预付的货款形成的是负债（合同负债），而不是收入。</p></blockquote><h2 id="二、会计等式" tabindex="-1">二、会计等式 <a class="header-anchor" href="#二、会计等式" aria-label="Permalink to &quot;二、会计等式&quot;">​</a></h2><h3 id="静态等式-基本等式" tabindex="-1">静态等式（基本等式） <a class="header-anchor" href="#静态等式-基本等式" aria-label="Permalink to &quot;静态等式（基本等式）&quot;">​</a></h3><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>资产</mtext><mo>=</mo><mtext>负债</mtext><mo>+</mo><mtext>所有者权益</mtext></mrow><annotation encoding="application/x-tex">\\text{资产} = \\text{负债} + \\text{所有者权益} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord cjk_fallback">资产</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord text"><span class="mord cjk_fallback">负债</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord cjk_fallback">所有者权益</span></span></span></span></span></span></p><p>这是资产负债表的编制基础。它表明企业所拥有的全部资源，要么来自债权人，要么来自所有者， 两者的求索权（claim）覆盖全部资产。</p><p>将所有者权益展开，可写成：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>资产</mtext><mo>=</mo><mtext>负债</mtext><mo>+</mo><mtext>实收资本</mtext><mo>+</mo><mtext>资本公积</mtext><mo>+</mo><mtext>盈余公积</mtext><mo>+</mo><mtext>未分配利润</mtext></mrow><annotation encoding="application/x-tex">\\text{资产} = \\text{负债} + \\text{实收资本} + \\text{资本公积} + \\text{盈余公积} + \\text{未分配利润} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord cjk_fallback">资产</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord text"><span class="mord cjk_fallback">负债</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord text"><span class="mord cjk_fallback">实收资本</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord text"><span class="mord cjk_fallback">资本公积</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord text"><span class="mord cjk_fallback">盈余公积</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord cjk_fallback">未分配利润</span></span></span></span></span></span></p><h3 id="动态等式" tabindex="-1">动态等式 <a class="header-anchor" href="#动态等式" aria-label="Permalink to &quot;动态等式&quot;">​</a></h3><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>利润</mtext><mo>=</mo><mtext>收入</mtext><mo>−</mo><mtext>费用</mtext><mo>+</mo><mtext>直接计入当期利润的利得</mtext><mo>−</mo><mtext>直接计入当期利润的损失</mtext></mrow><annotation encoding="application/x-tex">\\text{利润} = \\text{收入} - \\text{费用} + \\text{直接计入当期利润的利得} - \\text{直接计入当期利润的损失} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord cjk_fallback">利润</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord text"><span class="mord cjk_fallback">收入</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord text"><span class="mord cjk_fallback">费用</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord text"><span class="mord cjk_fallback">直接计入当期利润的利得</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord cjk_fallback">直接计入当期利润的损失</span></span></span></span></span></span></p><h3 id="扩展-综合-等式" tabindex="-1">扩展（综合）等式 <a class="header-anchor" href="#扩展-综合-等式" aria-label="Permalink to &quot;扩展（综合）等式&quot;">​</a></h3><p>把静态与动态两个等式结合起来，得到交易发生后的综合形式：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>资产</mtext><mo>+</mo><mtext>费用</mtext><mo>=</mo><mtext>负债</mtext><mo>+</mo><mtext>所有者权益</mtext><mo>+</mo><mtext>收入</mtext></mrow><annotation encoding="application/x-tex">\\text{资产} + \\text{费用} = \\text{负债} + \\text{所有者权益} + \\text{收入} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord text"><span class="mord cjk_fallback">资产</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord cjk_fallback">费用</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord text"><span class="mord cjk_fallback">负债</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord text"><span class="mord cjk_fallback">所有者权益</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord cjk_fallback">收入</span></span></span></span></span></span></p><p>理解方式：收入最终会增加所有者权益（在贷方），费用会减少所有者权益（在借方）， 把它们移动到等式左侧，正好与借贷记账法的记账方向一致。</p><h2 id="三、交易对等式的影响" tabindex="-1">三、交易对等式的影响 <a class="header-anchor" href="#三、交易对等式的影响" aria-label="Permalink to &quot;三、交易对等式的影响&quot;">​</a></h2><p>任何经济业务，对等式的影响只有以下四种基本类型：</p><table tabindex="0"><thead><tr><th>类型</th><th>资产</th><th>负债</th><th>所有者权益</th><th>举例</th></tr></thead><tbody><tr><td>①</td><td>增加</td><td>增加</td><td>—</td><td>向银行借入短期借款</td></tr><tr><td>②</td><td>减少</td><td>减少</td><td>—</td><td>以银行存款偿还应付账款</td></tr><tr><td>③</td><td>增加</td><td>—</td><td>增加</td><td>所有者投入资本</td></tr><tr><td>④</td><td>减少</td><td>—</td><td>减少</td><td>依法减资、分配现金股利</td></tr></tbody></table><p>若只在等式同一边发生增减（不改变总额），则属于：</p><ul><li><strong>资产内部一增一减</strong>：以银行存款购入设备；</li><li><strong>负债内部一增一减</strong>：开具商业汇票抵付应付账款；</li><li><strong>所有者权益内部一增一减</strong>：资本公积转增资本。</li></ul><blockquote><p><strong>结论</strong>：任何一笔业务至少影响两个会计科目，且必定保持 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>资产</mtext><mo>=</mo><mtext>负债</mtext><mo>+</mo><mtext>所有者权益</mtext></mrow><annotation encoding="application/x-tex">\\text{资产} = \\text{负债} + \\text{所有者权益}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord cjk_fallback">资产</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord text"><span class="mord cjk_fallback">负债</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord cjk_fallback">所有者权益</span></span></span></span></span> 成立， 这正是复式记账&quot;有借必有贷，借贷必相等&quot;的数学基础。</p></blockquote><h2 id="四、例题-五笔业务验证等式" tabindex="-1">四、例题：五笔业务验证等式 <a class="header-anchor" href="#四、例题-五笔业务验证等式" aria-label="Permalink to &quot;四、例题：五笔业务验证等式&quot;">​</a></h2><p>甲公司在 2026 年 10 月发生以下业务，假设期初资产 500 000 元、负债 200 000 元、 所有者权益 300 000 元。</p><table tabindex="0"><thead><tr><th>序号</th><th>业务</th><th>会计分录（元）</th></tr></thead><tbody><tr><td>1</td><td>收到投资者投入资金 100 000 元，存入银行</td><td>借：银行存款 100 000<br>贷：实收资本 100 000</td></tr><tr><td>2</td><td>以银行存款购入设备 40 000 元</td><td>借：固定资产 40 000<br>贷：银行存款 40 000</td></tr><tr><td>3</td><td>赊购原材料 20 000 元</td><td>借：原材料 20 000<br>贷：应付账款 20 000</td></tr><tr><td>4</td><td>以银行存款偿还前欠货款 15 000 元</td><td>借：应付账款 15 000<br>贷：银行存款 15 000</td></tr><tr><td>5</td><td>销售商品取得收入 60 000 元，款项已收，成本 45 000 元</td><td>借：银行存款 60 000<br>贷：主营业务收入 60 000<br>借：主营业务成本 45 000<br>贷：库存商品 45 000</td></tr></tbody></table><p><strong>期末计算</strong>：</p><ul><li>资产 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>=</mo><mn>500</mn><mtext> </mtext><mn>000</mn><mo>+</mo><mn>100</mn><mtext> </mtext><mn>000</mn><mo>−</mo><mn>40</mn><mtext> </mtext><mn>000</mn><mo>+</mo><mn>40</mn><mtext> </mtext><mn>000</mn><mo>+</mo><mn>20</mn><mtext> </mtext><mn>000</mn><mo>−</mo><mn>15</mn><mtext> </mtext><mn>000</mn><mo>+</mo><mn>60</mn><mtext> </mtext><mn>000</mn><mo>−</mo><mn>45</mn><mtext> </mtext><mn>000</mn><mo>=</mo><mn>620</mn><mtext> </mtext><mn>000</mn></mrow><annotation encoding="application/x-tex">= 500\\,000 + 100\\,000 - 40\\,000 + 40\\,000 + 20\\,000 - 15\\,000 + 60\\,000 - 45\\,000 = 620\\,000</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.3669em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">500</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">000</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">100</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">000</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">40</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">000</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">40</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">000</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">20</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">000</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">15</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">000</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">60</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">000</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">45</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">000</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">620</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">000</span></span></span></span> 元；</li><li>负债 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>=</mo><mn>200</mn><mtext> </mtext><mn>000</mn><mo>+</mo><mn>20</mn><mtext> </mtext><mn>000</mn><mo>−</mo><mn>15</mn><mtext> </mtext><mn>000</mn><mo>=</mo><mn>205</mn><mtext> </mtext><mn>000</mn></mrow><annotation encoding="application/x-tex">= 200\\,000 + 20\\,000 - 15\\,000 = 205\\,000</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.3669em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">200</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">000</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">20</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">000</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">15</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">000</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">205</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">000</span></span></span></span> 元；</li><li>所有者权益 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>=</mo><mn>300</mn><mtext> </mtext><mn>000</mn><mo>+</mo><mn>100</mn><mtext> </mtext><mn>000</mn><mo>+</mo><mn>60</mn><mtext> </mtext><mn>000</mn><mo>−</mo><mn>45</mn><mtext> </mtext><mn>000</mn><mo>=</mo><mn>415</mn><mtext> </mtext><mn>000</mn></mrow><annotation encoding="application/x-tex">= 300\\,000 + 100\\,000 + 60\\,000 - 45\\,000 = 415\\,000</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.3669em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">300</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">000</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">100</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">000</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">60</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">000</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">45</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">000</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">415</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">000</span></span></span></span> 元；</li><li>校验：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>620</mn><mtext> </mtext><mn>000</mn><mo>=</mo><mn>205</mn><mtext> </mtext><mn>000</mn><mo>+</mo><mn>415</mn><mtext> </mtext><mn>000</mn></mrow><annotation encoding="application/x-tex">620\\,000 = 205\\,000 + 415\\,000</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">620</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">000</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">205</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">000</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">415</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">000</span></span></span></span>，等式成立。</li></ul><h2 id="五、常见误区" tabindex="-1">五、常见误区 <a class="header-anchor" href="#五、常见误区" aria-label="Permalink to &quot;五、常见误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>正确说法</th></tr></thead><tbody><tr><td>资产就是&quot;钱&quot;</td><td>资产是资源，应收账款、专利都属于资产</td></tr><tr><td>收入增加必然使资产增加</td><td>也可能同时减少负债，例如以商品抵偿预收账款</td></tr><tr><td>所有者权益等于股东投入的本金</td><td>它还包含留存收益、其他综合收益等累计结果</td></tr><tr><td>借贷就是&quot;借入/借出&quot;</td><td>&quot;借&quot;&quot;贷&quot;只是记账符号，表示左方与右方</td></tr></tbody></table><h2 id="速查清单" tabindex="-1">速查清单 <a class="header-anchor" href="#速查清单" aria-label="Permalink to &quot;速查清单&quot;">​</a></h2><ol><li>判断要素先看<strong>时点量</strong>还是<strong>期间量</strong>：时点进资产负债表，期间进利润表；</li><li>写分录前先问两个问题：涉及哪几个科目？各科目的金额是增还是减？</li><li>分录写完立即校验：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>资产</mtext><mo>=</mo><mtext>负债</mtext><mo>+</mo><mtext>所有者权益</mtext></mrow><annotation encoding="application/x-tex">\\text{资产} = \\text{负债} + \\text{所有者权益}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord cjk_fallback">资产</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord text"><span class="mord cjk_fallback">负债</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord cjk_fallback">所有者权益</span></span></span></span></span>；</li><li>遇到&quot;预收&quot;&quot;预付&quot;不要凭直觉归类，回到定义判断权利义务。</li></ol><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><ul><li>《企业会计准则——基本准则》</li><li>财政部《企业会计准则详解》第一章</li></ul>',38)])])}const x=a(p,[["render",m]]);export{d as __pageData,x as default};
